fn mix(h:u32,b:u8)u32{return (h^b)*%16777619;}
fn nextPerm(a:*[6]i32,n:usize)bool{var i=n-1;while(i>0 and a[i-1]>=a[i]):(i-=1){}if(i==0)return false;var j=n-1;while(a[j]<=a[i-1]):(j-=1){}const t=a[i-1];a[i-1]=a[j];a[j]=t;var l=i;var r=n-1;while(l<r):(l+=1){const x=a[l];a[l]=a[r];a[r]=x;r-=1;}return true;}
export fn permutations(v:[*c]const i64,n:usize)i64{if(v==null or n<2 or n>7 or v[0]<1 or v[0]>6 or n!=@as(usize,@intCast(v[0]))+1)return -1;const count:usize=@intCast(v[0]);var a:[6]i32=undefined;for(0..count)|i|{if(v[i+1] < -2147483648 or v[i+1]>2147483647)return -1;a[i]=@intCast(v[i+1]);if(i>0 and a[i-1]>=a[i])return -1;}var h:u32=2166136261;while(true){for(a[0..count])|value|{const u:u32=@bitCast(value);for(0..4)|b|h=mix(h,@truncate(u>>(8*b)));}h=mix(h,255);if(!nextPerm(&a,count))break;}return @intCast(h);}
